import { quotePremium, type Customer, type Item } from './premium.js';
import { ClaimRejectedError, openPolicy, processClaim, type Incident, type Policy } from './claim.js';

export interface QuoteStep {
  op: 'quote';
  items: Item[];
}

export interface ClaimStep {
  op: 'claim';
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export function runScenario(scenario: Scenario): StepResult[] {
  const policies = new Map<number, Policy>();
  let quotesSoFar = 0;

  return scenario.steps.map((step, index) => {
    if (step.op === 'quote') {
      const premium = quotePremium(step.items, scenario.customer, quotesSoFar);
      quotesSoFar += 1;
      policies.set(index, openPolicy(step.items));
      return { premium };
    }
    const policy = policies.get(step.policy);
    if (policy === undefined) {
      throw new ClaimRejectedError(`no policy created by step ${step.policy}`);
    }
    return processClaim(policy, step.incident);
  });
}
EOF
