export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Customer {
  yearsWithMHPCO: number;
}

const PROCESSING_FEE = 5;

const MAIN_ITEMS: Record<string, { value: number; premium: number }> = {
  sword: { value: 1000, premium: 100 },
  amulet: { value: 600, premium: 60 },
  staff: { value: 800, premium: 80 },
  potion: { value: 400, premium: 40 },
};

const COMPONENT_TYPES = ['rune', 'moonstone'];
const COMPONENT_VALUE = 250;
const COMPONENT_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const CURSE_SURCHARGE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
const HIGH_ENCHANTMENT_LEVEL = 5;

const LOYALTY_DISCOUNT = 0.2;
const LOYALTY_YEARS = 2;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const FOLLOW_UP_DISCOUNT = 0.15;

export class UnknownItemTypeError extends Error {
  constructor(type: string) {
    super(`unknown item type: ${type}`);
  }
}

export function isComponent(type: string): boolean {
  return COMPONENT_TYPES.includes(type);
}

export function insuranceValueOf(item: Item): number {
  const main = MAIN_ITEMS[item.type];
  if (main !== undefined) return main.value;
  if (isComponent(item.type)) return COMPONENT_VALUE;
  throw new UnknownItemTypeError(item.type);
}

/**
 * Base premium per item, in the order the items were given. Components of the
 * same type form a block when there are exactly three; the block premium is
 * split evenly across its members so item-specific modifiers have a base.
 */
export function itemBasePremiums(items: Item[]): number[] {
  const premiums = new Array<number>(items.length);
  const componentIndices = new Map<string, number[]>();

  items.forEach((item, index) => {
    const main = MAIN_ITEMS[item.type];
    if (main !== undefined) {
      premiums[index] = main.premium;
    } else if (isComponent(item.type)) {
      const group = componentIndices.get(item.type) ?? [];
      group.push(index);
      componentIndices.set(item.type, group);
    } else {
      throw new UnknownItemTypeError(item.type);
    }
  });

  for (const indices of componentIndices.values()) {
    const isBlock = indices.length === BLOCK_SIZE;
    const each = isBlock ? BLOCK_PREMIUM / BLOCK_SIZE : COMPONENT_PREMIUM;
    for (const index of indices) premiums[index] = each;
  }

  return premiums;
}

/** Item-specific surcharges, each applied to the base premium of its own item. */
export function itemSurcharges(items: Item[]): number {
  const bases = itemBasePremiums(items);
  return items.reduce((sum, item, index) => {
    const base = bases[index];
    const curse = item.cursed === true ? base * CURSE_SURCHARGE : 0;
    const enchanted =
      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL
        ? base * HIGH_ENCHANTMENT_SURCHARGE
        : 0;
    return sum + curse + enchanted;
  }, 0);
}

export function policyBasePremium(items: Item[]): number {
  return itemBasePremiums(items).reduce((sum, premium) => sum + premium, 0);
}

/**
 * Policy-wide modifiers, each applied to the policy base premium. Every item in
 * a quote counts as a first insurance regardless of customer history, so the
 * initial assessment surcharge is always charged.
 */
function policySurcharges(base: number, customer: Customer, previousQuotes: number): number {
  const loyalty = customer.yearsWithMHPCO >= LOYALTY_YEARS ? -base * LOYALTY_DISCOUNT : 0;
  const firstInsurance = base * FIRST_INSURANCE_SURCHARGE;
  const followUp = previousQuotes > 0 ? -base * FOLLOW_UP_DISCOUNT : 0;
  return loyalty + firstInsurance + followUp;
}

/** Rounds up: whole G, in the MHPCO's favour. */
function roundPremium(amount: number): number {
  return Math.ceil(amount);
}

export function quotePremium(
  items: Item[],
  customer: Customer,
  previousQuotes: number,
): number {
  const base = policyBasePremium(items);
  const total =
    base + itemSurcharges(items) + policySurcharges(base, customer, previousQuotes) + PROCESSING_FEE;
  return roundPremium(total);
}
===== CLAIM =====
import { insuranceValueOf, type Item } from './premium.js';

const DEDUCTIBLE = 100;
const CAP_FACTOR = 2;
const HALVING_ENCHANTMENT_LEVEL = 8;
const HALVING_RATE = 0.5;

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

/** A policy holds the insured items and tracks how much of its cap is left. */
export interface Policy {
  items: Item[];
  remainingCap: number;
}

export class ClaimRejectedError extends Error {}

export function openPolicy(items: Item[]): Policy {
  const insuranceSum = items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
  return { items, remainingCap: insuranceSum * CAP_FACTOR };
}

/**
 * Highly enchanted items are reimbursed at half the damage; dragon material is
 * reimbursed in full, which is also the default. Where both clauses apply, the
 * halving wins. The deductible comes off afterwards.
 */
function payoutFor(item: Item, amount: number): number {
  const reimbursable =
    (item.enchantment ?? 0) >= HALVING_ENCHANTMENT_LEVEL ? amount * HALVING_RATE : amount;
  return Math.max(0, reimbursable - DEDUCTIBLE);
}

/** Rounds down: whole G, in the MHPCO's favour. */
function roundPayout(amount: number): number {
  return Math.floor(amount);
}

/**
 * Matches every damage to a distinct insured item, so two damages of the same
 * type require two insured items of that type. Rejects the whole claim when a
 * damage cannot be matched or its amount is negative.
 */
function matchDamages(policy: Policy, damages: Damage[]): Item[] {
  const unclaimed = [...policy.items];
  return damages.map((damage) => {
    if (damage.amount < 0) {
      throw new ClaimRejectedError(`negative damage amount: ${damage.amount}`);
    }
    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
    if (index === -1) {
      throw new ClaimRejectedError(`not insured under this policy: ${damage.itemType}`);
    }
    return unclaimed.splice(index, 1)[0];
  });
}

export function processClaim(policy: Policy, incident: Incident): ClaimResult {
  const damagedItems = matchDamages(policy, incident.damages);
  const desired = incident.damages.reduce(
    (sum, damage, index) => sum + payoutFor(damagedItems[index], damage.amount),
    0,
  );
  const payout = roundPayout(Math.min(desired, policy.remainingCap));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}

